// SPDX-License-Identifier: GPL-3.0

pragma solidity >=0.7.0 <0.9.0;

import {IERC20} from "@openzeppelin/contracts/interfaces/IERC20.sol";
import {Order} from "./types/Trade.sol";

contract TokenMarketPlace {
    uint public constant TOKEN_PRICE = 1 ether;
    uint private reservedOrderedTokens;
    IERC20 public  ANVI_TOKEN;

    mapping(uint256 => Order) private orders;
    uint256 private nextOrderId;

    error TokenMarketPlace_ZeroNumberOfToken(uint numberOfTokens);
    error TokenMarketPlace_InsufficientEthPayment(uint expectedAmmount,uint actualAmmount);
    error TokenMarketPlace_InsufficientTokenInMarketPlace(uint expectedToken,uint actualToken);
    error TokenMarketplace_InsufficientBalance(uint balance,uint numberOfTokens);

    constructor(address _anviToken){
        ANVI_TOKEN = IERC20(_anviToken);
    }

    function _getAnviTokenMarketBalance() internal view returns(uint256) {
        return ANVI_TOKEN.balanceOf(address(this));
    }

    function _isNumberOfTokenZero(uint256 numberOfTokens) internal pure {
        if(numberOfTokens == 0){
            revert TokenMarketPlace_ZeroNumberOfToken(numberOfTokens); 
        }
    }

    function _checkEthPayment(uint256 numberOfTokens) internal view {
        if(numberOfTokens*TOKEN_PRICE != msg.value){
            revert TokenMarketPlace_InsufficientEthPayment(numberOfTokens*TOKEN_PRICE, msg.value);
        }
    }

    function _checkUserTokenExist(address account,uint256 numberOfTokens) internal view {
        uint256 balance = ANVI_TOKEN.balanceOf(account);


        if (numberOfTokens > balance) {
            revert TokenMarketplace_InsufficientBalance(balance,numberOfTokens);
        }

    }

    function _isAnviTokenMarketPlaceHaveToken(uint256 numberOfTokens) internal view {
        if(_getAnviTokenMarketBalance() < numberOfTokens){
            revert TokenMarketPlace_InsufficientTokenInMarketPlace(numberOfTokens,_getAnviTokenMarketBalance()); 
        }
    }

    function buyTokenFromMarketPlace(uint256 numberOfTokens) external payable {
        _isNumberOfTokenZero(numberOfTokens);
        _checkEthPayment(numberOfTokens);
        _isAnviTokenMarketPlaceHaveToken(numberOfTokens);
        ANVI_TOKEN.transfer(msg.sender, numberOfTokens);
    }

    function createSellOrder(uint256 numberOfTokens) external  {
        _isNumberOfTokenZero(numberOfTokens);
        _checkUserTokenExist(msg.sender , numberOfTokens);
        uint allowance = ANVI_TOKEN.allowance(msg.sender, address(this));
        if (allowance < numberOfTokens){
                        revert TokenMarketPlace_InsufficientTokenInMarketPlace(numberOfTokens,_getAnviTokenMarketBalance()); 

        }
        Order memory order = Order({
            orderId: nextOrderId,
            seller: msg.sender,
            numberOfTokens: numberOfTokens,
            isActive: true
        });
        orders[nextOrderId] = order;
        nextOrderId++;
        ANVI_TOKEN.transferFrom(msg.sender, address(this), numberOfTokens);
        reservedOrderedTokens += numberOfTokens; 
    }
}

